function DomainManager({ projects, notify }: { projects: Project[]; notify: (m: string) => void }) {
  const [domains, setDomains] = useState<Domain[]>([]), [error, setError] = useState(''), [busy, setBusy] = useState(false), [create, setCreate] = useState(false), [remove, setRemove] = useState<Domain | null>(null);
  const refresh = useCallback(() => api<{ domains: Domain[] }>('/domains').then(d => setDomains(d.domains)).catch(e => setError(e.message)), []); useEffect(() => { void refresh(); }, [refresh]);
  const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); setBusy(true); setError(''); try { await api(`/projects/${form.get('projectId')}/domains`, post({ hostname: form.get('hostname') })); setCreate(false); await refresh(); notify('Domain added. Verify DNS ownership to continue.'); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } };
  return <>{error && <div className="alert error" role="alert"><CircleAlert size={16} />{error}</div>}<div className="info-banner"><span className="info-banner-icon"><Globe2 size={23} /></span><div><h3>Your website. Your address.</h3><p>Domain ownership is verified through DNS before any hostname is attached.</p></div><Button variant="primary" disabled={!projects.length} onClick={() => setCreate(true)}><Plus size={15} />Connect domain</Button></div>{domains.length ? domains.map(d => <Panel key={d.id} title={d.hostname} subtitle={projects.find(p => p.id === d.projectId)?.name || d.projectId} action={<Status value={d.verifiedAt ? 'verified' : 'pending'} />}><div className="panel-body"><div className="dns-instructions"><h3>Verify domain ownership</h3><p>Add this TXT record with your DNS provider. DNS changes can take time to propagate.</p><div className="dns-record"><div><small>TYPE</small><strong>TXT</strong></div><div><small>NAME</small><code>_deployhub.{d.hostname}</code></div><div><small>VALUE</small><code>{d.verificationToken}</code></div><CopyButton value={d.verificationToken} /></div><p className="field-note">After ownership verification, point a CNAME for this hostname to {projects.find(p => p.id === d.projectId)?.productionUrl?.replace(/^https?:\/\//, '').split(':')[0] || 'your project hostname'}. Apex domains require A / AAAA records to your VPS.</p></div><div className="domain-footer"><span className="muted"><ShieldCheck size={15} />TLS status: {d.sslStatus || 'pending'}</span><div className="inline-row"><Button variant="ghost" onClick={() => setRemove(d)}><Trash2 size={14} />Remove</Button><Button disabled={busy} onClick={async () => { setBusy(true); setError(''); try { await api(`/domains/${d.id}/verify`, post({})); await refresh(); notify('DNS verification checked'); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }}><RefreshCw size={14} />Verify DNS</Button></div></div></div></Panel>) : <Panel title="Custom domains"><Empty icon={Globe2} title="Put your own name on it" description={projects.length ? 'Connect a domain to one of your projects and follow the DNS verification steps.' : 'Create a project first, then connect a custom domain.'} action={projects.length > 0 && <Button onClick={() => setCreate(true)}><Plus size={15} />Connect a domain</Button>} /></Panel>}<div className="alert info"><ShieldCheck size={17} /><span>Automatic HTTPS requires the production Caddy proxy and public DNS. A verified DNS record alone does not confirm that a TLS certificate has been issued.</span></div>{create && <Modal title="Connect custom domain" onClose={() => !busy && setCreate(false)}><form onSubmit={submit}><div className="panel-body form-body">{error && <div className="alert error">{error}</div>}<Field label="Project"><select name="projectId" required>{projects.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label="Domain name" hint="Enter a hostname without https:// or a path."><input name="hostname" placeholder="www.yourwebsite.com" required pattern="[A-Za-z0-9.-]+" /></Field></div><div className="modal-actions"><Button onClick={() => setCreate(false)}>Cancel</Button><Button type="submit" variant="primary" disabled={busy}><Globe2 size={15} />Add domain</Button></div></form></Modal>}{remove && <Modal title={`Remove ${remove.hostname}?`} onClose={() => setRemove(null)}><p className="modal-description">This hostname will stop routing to this project. Your generated project URL remains available.</p><div className="modal-actions"><Button onClick={() => setRemove(null)}>Cancel</Button><Button variant="danger" disabled={busy} onClick={async () => { setBusy(true); try { await api(`/domains/${remove.id}`, { method: 'DELETE' }); setRemove(null); await refresh(); notify('Domain removed'); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }}>Remove domain</Button></div></Modal>}</>;
}

function FileManager({ projects, onUpload }: { projects: Project[]; onUpload: (project: Project) => void }) {
  const [projectId, setProjectId] = useState(projects[0]?.id || ''), [path, setPath] = useState(''), [files, setFiles] = useState<{ name: string; path: string; type: string; sizeBytes: number }[]>([]), [error, setError] = useState(''), [loading, setLoading] = useState(false), [search, setSearch] = useState(''), [content, setContent] = useState<{ path: string; text: string } | null>(null);
  useEffect(() => { if (!projectId) return; let alive = true; setLoading(true); setError(''); api<{ files: typeof files }>(`/projects/${projectId}/files?path=${encodeURIComponent(path)}`).then(d => { if (alive) setFiles(d.files); }).catch(e => { if (alive) { setFiles([]); setError(e.message); } }).finally(() => { if (alive) setLoading(false); }); return () => { alive = false; }; }, [projectId, path]);
  const project = projects.find(p => p.id === projectId);
  const view = async (filePath: string) => { setError(''); try { const response = await fetch(`/api/v1/projects/${projectId}/files/content?path=${encodeURIComponent(filePath)}`, { credentials: 'include' }); if (!response.ok) { const d = await response.json().catch(() => ({})); throw new Error(d.error?.message || d.error || 'Unable to preview this file'); } setContent({ path: filePath, text: await response.text() }); } catch (e) { setError((e as Error).message); } };
  return <>{error && <div className="alert error" role="alert"><CircleAlert size={16} />{error}</div>}<div className="toolbar"><select aria-label="File manager project" value={projectId} onChange={e => { setProjectId(e.target.value); setPath(''); }}>{!projects.length && <option value="">No projects</option>}{projects.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select><div className="search-input"><Search size={16} /><input placeholder="Find a file in this folder…" aria-label="Search files" value={search} onChange={e => setSearch(e.target.value)} /></div>{project && <Button variant="primary" onClick={() => onUpload(project)}><Upload size={15} />Upload a new version</Button>}</div><Panel title="Deployed files" subtitle="Read-only view of the current production artifact." action={project?.currentDeploymentId && <a className="button secondary" href={`/api/v1/deployments/${project.currentDeploymentId}/artifact`}><ArrowDownToLine size={15} />Download ZIP</a>}><div className="file-breadcrumb"><button onClick={() => setPath('')}><FolderOpen size={14} />Root</button>{path.split('/').filter(Boolean).map((segment, i, segments) => <span key={i}><ChevronRight size={12} /><button onClick={() => setPath(segments.slice(0, i + 1).join('/'))}>{segment}</button></span>)}</div>{loading ? <div className="inline-loading"><LoaderCircle size={20} className="spin" />Reading deployment files…</div> : files.length ? <div className="table-scroll"><table><thead><tr><th>Name</th><th>Type</th><th>Size</th><th /></tr></thead><tbody>{path && <tr><td colSpan={4}><button className="file-name" onClick={() => setPath(path.split('/').slice(0, -1).join('/'))}><Folder size={17} />..</button></td></tr>}{files.filter(f => f.name.toLowerCase().includes(search.toLowerCase())).map(f => <tr key={f.path}><td><button className="file-name" onClick={() => f.type === 'directory' ? setPath(f.path) : void view(f.path)}>{f.type === 'directory' ? <Folder size={17} className="folder-icon" /> : <FileCode2 size={17} />}<strong>{f.name}</strong></button></td><td className="muted">{f.type}</td><td className="muted">{f.type === 'directory' ? '—' : bytes(f.sizeBytes)}</td><td><button className="text-button" onClick={() => f.type === 'directory' ? setPath(f.path) : void view(f.path)}>{f.type === 'directory' ? 'Open folder' : 'View text'}<ChevronRight size={13} /></button></td></tr>)}</tbody></table></div> : <Empty icon={FolderOpen} title="No deployed files to browse" description="Publish a production deployment to inspect its immutable artifact here." />}</Panel><div className="alert info"><ShieldCheck size={16} /><span>Published artifacts are immutable. To edit, rename, or remove files, update your local source and upload a new version.</span></div>{content && <Modal title={content.path} onClose={() => setContent(null)} large><div className="file-preview"><pre>{content.text}</pre></div><div className="modal-actions"><CopyButton value={content.text} /><Button onClick={() => setContent(null)}>Close</Button></div></Modal>}</>;
}

function Integration() {
  const [tab, setTab] = useState('cli');
  return <><section className="integration-hero"><span className="integration-icon"><Terminal size={30} /></span><div><span className="launch-badge">MADE FOR YOUR WORKFLOW</span><h2>Your editor. Your deployment pipeline.</h2><p>Deploy directly from your terminal, Codex, VS Code, or an MCP-compatible agent.</p></div><span className="cli-chip">$ deployhub deploy</span></section><div className="tabs">{[['cli', 'DeployHub CLI'], ['codex', 'Codex & MCP'], ['api', 'REST API']].map(([value, label]) => <button key={value} className={tab === value ? 'active' : ''} onClick={() => setTab(value)}>{label}</button>)}</div>{tab === 'cli' && <div className="docs-content"><Panel title="01 · Install & authenticate" subtitle="Requires Node.js 22 or newer. Run from the DeployHub repository."><div className="panel-body"><CodeBlock>{'npm install --global ./apps/cli\ndeployhub --url http://localhost:4100 login\n# Enter a scoped API key when prompted'}</CodeBlock><p className="muted">Use your public management API URL on a production server. Create a key with read and deploy permissions, plus manage when creating projects.</p></div></Panel><Panel title="02 · Link your project" subtitle="Run inside your website folder."><div className="panel-body"><CodeBlock>{'deployhub init\ndeployhub deploy --preview\ndeployhub status\ndeployhub logs'}</CodeBlock><p className="muted">The CLI excludes node_modules, Git metadata, environment files, and local credentials. Review your source and .deployhubignore before uploading.</p></div></Panel><Panel title="03 · Publish a release" subtitle="Production changes require explicit authorization."><div className="panel-body"><CodeBlock>{'deployhub deploy --prod\n# --prod explicitly authorizes replacing production\ndeployhub open\n\n# Deploy prebuilt files and return structured output\ndeployhub deploy --dir ./dist --preview --json'}</CodeBlock><p className="muted">The CLI waits for a real deployment result and returns a verified URL. Failed deployments exit with a nonzero status.</p></div></Panel></div>}{tab === 'codex' && <div className="docs-content"><Panel title="A repeatable Codex workflow" subtitle="Use the CLI as the primary integration."><div className="panel-body"><p>Give Codex the reusable instructions in <code>templates/AGENTS.md</code>, then request a preview deployment after your website checks pass.</p><CodeBlock>{'Finish the website and run its checks.\nUse DeployHub CLI to deploy a preview.\nWait for verification and return the actual preview URL.\nAsk for production authorization before replacing the live site.'}</CodeBlock></div></Panel><Panel title="Local MCP bridge" subtitle="A local server can read only explicitly authorized roots."><div className="panel-body"><p>Install and configure the MCP package following <code>docs/integrations.md</code>. Set API credentials through environment variables; never paste tokens into committed configuration.</p><CodeBlock>{'{\n  "mcpServers": {\n    "deployhub": {\n      "command": "node",\n      "args": ["/absolute/path/to/deployhub/apps/mcp-server/dist/index.js"],\n      "env": {\n        "DEPLOYHUB_URL": "http://localhost:4100",\n        "DEPLOYHUB_ALLOWED_ROOTS": "/absolute/path/to/your/websites"\n      }\n    }\n  }\n}'}</CodeBlock><div className="alert info"><ShieldCheck size={16} /><span>Provide DEPLOYHUB_TOKEN through a secret-capable process environment. A remote MCP server cannot read folders on your computer.</span></div></div></Panel></div>}{tab === 'api' && <div className="docs-content"><Panel title="An API for your release workflow" subtitle="Versioned REST endpoints at /api/v1."><div className="panel-body"><CodeBlock>{'curl "$DEPLOYHUB_URL/api/v1/projects" \\\n  -H "Authorization: Bearer $DEPLOYHUB_TOKEN"\n\ncurl "$DEPLOYHUB_URL/api/v1/projects/PROJECT_ID/deployments" \\\n  -H "Authorization: Bearer $DEPLOYHUB_TOKEN" \\\n  -F environment=preview \\\n  -F archive=@website.zip'}</CodeBlock><p className="muted">Read the returned deployment ID, poll its status, and inspect the logs. An accepted upload means the release is queued; only a verified deployment is marked live.</p><a className="button secondary" href="/api/v1/openapi.json" target="_blank" rel="noreferrer"><FileCode2 size={15} />Open API specification<ArrowUpRight size={14} /></a></div></Panel><Panel title="Core endpoints"><div className="endpoint-list">{[['POST', '/projects', 'Create a project'], ['POST', '/projects/:id/deployments', 'Upload a release'], ['GET', '/deployments/:id', 'Check real deployment status'], ['GET', '/deployments/:id/logs', 'Read build output'], ['POST', '/deployments/:id/promote', 'Authorize a production switch'], ['POST', '/deployments/:id/rollback', 'Restore a retained artifact']].map(([method, route, description]) => <div key={route}><span className={`method ${method.toLowerCase()}`}>{method}</span><code>{route}</code><span>{description}</span></div>)}</div></Panel></div>}</>;
}

function EnvironmentManager({ projectId, notify }: { projectId: string; notify: (message: string) => void }) {
  const [variables, setVariables] = useState<{ id: string; name: string; environment: string }[]>([]), [create, setCreate] = useState(false), [error, setError] = useState(''), [busy, setBusy] = useState(false), [remove, setRemove] = useState<{ id: string; name: string } | null>(null);
  const refresh = useCallback(() => api<{ variables: typeof variables }>(`/projects/${projectId}/environment`).then(d => setVariables(d.variables)).catch(e => setError(e.message)), [projectId]);
  useEffect(() => { void refresh(); }, [refresh]);
  const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.currentTarget)); setBusy(true); setError(''); try { await api(`/projects/${projectId}/environment`, { method: 'PUT', body: JSON.stringify(values) }); setCreate(false); await refresh(); notify('Environment variable saved. Redeploy to apply it.'); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } };
  return <><Panel title="Environment variables" subtitle="Encrypted, write-only values for isolated builds. Redeploy to apply changes." action={<Button onClick={() => setCreate(true)}><Plus size={14} />Add variable</Button>}>{error && <div className="alert error" role="alert">{error}</div>}{variables.length ? <div className="table-scroll"><table><thead><tr><th>Variable</th><th>Value</th><th>Environment</th><th /></tr></thead><tbody>{variables.map(v => <tr key={v.id}><td><code>{v.name}</code></td><td className="muted">••••••••••••</td><td><span className={`environment ${v.environment}`}><span />{v.environment}</span></td><td className="align-right"><Button variant="ghost" onClick={() => setRemove(v)}><Trash2 size={14} />Remove</Button></td></tr>)}</tbody></table></div> : <div className="panel-body"><p className="muted">No environment variables configured. Static HTML sites usually need none. Variables used by a frontend build may be included in the public bundle; keep private credentials out of browser code.</p></div>}</Panel>{create && <Modal title="Set environment variable" onClose={() => !busy && setCreate(false)}><form onSubmit={submit}><div className="panel-body form-body">{error && <div className="alert error">{error}</div>}<Field label="Variable name"><input name="name" placeholder="PUBLIC_API_URL" pattern="[A-Z_][A-Z0-9_]*" maxLength={128} required autoComplete="off" /></Field><Field label="Value" hint="Encrypted at rest and never returned by the API. Setting an existing name replaces its value."><input name="value" type="password" autoComplete="new-password" required maxLength={8192} /></Field><Field label="Environment"><select name="environment"><option value="preview">Preview</option><option value="production">Production</option></select></Field></div><div className="modal-actions"><Button onClick={() => setCreate(false)}>Cancel</Button><Button variant="primary" type="submit" disabled={busy}>{busy && <LoaderCircle size={14} className="spin" />}Save variable</Button></div></form></Modal>}{remove && <Modal title={`Remove ${remove.name}?`} onClose={() => setRemove(null)}><p className="modal-description">This variable will be absent from future builds. Existing artifacts remain unchanged.</p><div className="modal-actions"><Button onClick={() => setRemove(null)}>Cancel</Button><Button variant="danger" disabled={busy} onClick={async () => { setBusy(true); try { await api(`/projects/${projectId}/environment/${remove.id}`, { method: 'DELETE' }); setRemove(null); await refresh(); notify('Environment variable removed'); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }}>Remove variable</Button></div></Modal>}</>;
}

function BuildConfiguration({ project, onSaved }: { project: Project; onSaved: (p: Project) => void }) {
  const [editing, setEditing] = useState(false), [error, setError] = useState(''), [busy, setBusy] = useState(false);
  const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setBusy(true); setError(''); const fields = Object.fromEntries(new FormData(event.currentTarget)); try { const p = await api<Project>(`/projects/${project.id}`, { method: 'PATCH', body: JSON.stringify(fields) }); onSaved(p); setEditing(false); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } };
  return <><Panel title="Build configuration" action={<button className="text-button" onClick={() => setEditing(true)}><Settings size={12} />Edit settings</button>}><dl className="definition-list"><div><dt>Framework</dt><dd>{project.framework || 'auto'}</dd></div><div><dt>Root directory</dt><dd><code>{project.rootDirectory || '.'}</code></dd></div><div><dt>Install command</dt><dd><code>{project.installCommand || 'Automatic'}</code></dd></div><div><dt>Build command</dt><dd><code>{project.buildCommand || 'Automatic'}</code></dd></div><div><dt>Output directory</dt><dd><code>{project.outputDirectory || 'Automatic'}</code></dd></div></dl></Panel>{editing && <Modal title="Project settings" onClose={() => !busy && setEditing(false)} large><form onSubmit={submit}><div className="panel-body form-body">{error && <div className="alert error">{error}</div>}<div className="two-fields"><Field label="Project name"><input name="name" required defaultValue={project.name} maxLength={100} /></Field><Field label="Framework"><select name="framework" defaultValue={project.framework || 'auto'}>{['auto','static','vite','react','vue','angular','astro','svelte','next-static','next','nuxt','node'].map(f => <option key={f} value={f}>{f}</option>)}</select></Field></div><Field label="Description"><textarea name="description" defaultValue={project.description || ''} rows={2} maxLength={2000} /></Field><div className="two-fields"><Field label="Root directory"><input name="rootDirectory" defaultValue={project.rootDirectory || '.'} /></Field><Field label="Output directory"><input name="outputDirectory" defaultValue={project.outputDirectory || ''} placeholder="Automatic" /></Field></div><div className="two-fields"><Field label="Install command"><input name="installCommand" defaultValue={project.installCommand || ''} placeholder="Automatic" /></Field><Field label="Build command"><input name="buildCommand" defaultValue={project.buildCommand || ''} placeholder="Automatic" /></Field></div><div className="alert info"><ShieldCheck size={16} /><span>The project slug and production URL remain permanent. Build settings apply to future deployments. Server-rendered applications need a runtime adapter; source builds require Docker.</span></div></div><div className="modal-actions"><Button onClick={() => setEditing(false)}>Cancel</Button><Button variant="primary" disabled={busy} type="submit">{busy && <LoaderCircle size={14} className="spin" />}Save settings</Button></div></form></Modal>}</>;
}
